235	    let mut st: libc::stat = unsafe { std::mem::zeroed() };
236	    if unsafe { libc::fstat(fd, &mut st) } != 0 {
237	        // Without a fresh stat result the actual on-disk mode cannot be
238	        // confirmed, so the requirement cannot be met -- say so explicitly
239	        // rather than surface a bare errno string.
240	        let e = std::io::Error::last_os_error();
241	        return Err(std::io::Error::new(
