1	//! Regression coverage for keygen's write/sync contract on Unix: what must
2	//! hold while the 32 key bytes are being saved, and when saving cannot
3	//! complete (see README "文件权限" for the permission side, covered in
4	//! keygen_permissions.rs).
5	//!
6	//! What is protected here:
7	//!
8	//! * Partial writes: if the kernel only accepts part of the buffer per
9	//!   write() call, the remaining bytes still land -- no byte already written
10	//!   is duplicated, no later byte is skipped. The final file is exactly the
11	//!   32 raw key bytes (no newline, header, or trailer), mode 0600.
12	//! * Recoverable interruption: write() failing with EINTR and then
13	//!   succeeding still completes the same generation with exit code 0.
14	//! * Success is only reported after every byte is written *and* fsynced:
15	//!   exit 0, the usual "Key saved to ..." line on stdout, empty stderr.
16	//! * Unrecoverable write error after some bytes landed, and fsync failure
17	//!   after all bytes landed: exit 1, stderr explains the failure (naming
18	//!   the target), stdout carries no success message, the file created by
19	//!   this invocation is removed, and neither the parent directory's
20	//!   permissions nor pre-existing siblings are touched. Key bytes never
21	//!   appear on stdout/stderr, on success or on failure.
22	//! * Zero-byte write: write() accepting 0 bytes while bytes remain -- no
23	//!   progress, yet no errno either -- is neither success nor a recoverable
24	//!   interruption. Whether it happens before any byte landed or midway,
25	//!   the command must end (not hang in the save loop) with exit 1, an
26	//!   explanation naming the target on stderr, empty stdout, and no file
27	//!   left at the target: no empty file, no partial key, no zero-padded
28	//!   32-byte stand-in.
29	//! * Close-stage failure: all 32 bytes written and fsynced, then close()
30	//!   reporting an unrecoverable error is still a failed save -- exit 1,
31	//!   empty stdout, stderr naming the target and the close-stage error, and
32	//!   the file removed even though it holds 32 bytes with mode 0600. If the
33	//!   system also refuses the removal, stderr keeps the close failure and
34	//!   additionally warns that cleanup did not complete and this run's key
35	//!   file may remain at the target; the parent directory's permissions are
36	//!   never loosened to force the cleanup, and the key is not stashed under
37	//!   another name. A close() that merely reports EINTR after releasing the
38	//!   descriptor is not a failure: the save is reported as usual, exit 0.
39	//!
40	//! The faults are injected by the LD_PRELOAD shim (tests/support/permfail),
41	//! which also traces every write()/fsync() on the key descriptor so the
42	//! byte stream can be checked for gaps, duplicates, and leaks.
43	#![cfg(unix)]
44	
45	use std::collections::HashMap;
46	use std::fs;
47	use std::os::unix::fs::{MetadataExt, PermissionsExt};
48	use std::path::{Path, PathBuf};
49	use std::process::Command;
50	use std::sync::atomic::{AtomicU64, Ordering};
51	
52	const KEY_LEN: usize = 32;
53	const MODE_0600: u32 = 0o600;
54	const UMASKS: [u32; 3] = [0o022, 0o000, 0o777];
55	
56	fn bin() -> PathBuf {
57	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
58	}
59	
60	fn permfail_so() -> Option<PathBuf> {
61	    option_env!("WRAPFILE_PERMFAIL_SO").map(PathBuf::from)
62	}
63	
64	// ---------------------------------------------------------------------------
65	// scratch directory
66	// ---------------------------------------------------------------------------
67	
68	struct Tmp {
69	    path: PathBuf,
70	}
71	
72	impl Tmp {
73	    fn new(label: &str) -> Tmp {
74	        static SEQ: AtomicU64 = AtomicU64::new(0);
75	        let path = std::env::temp_dir().join(format!(
76	            "wrapfile-keygen-write-tests-{}-{}-{}",
77	            std::process::id(),
78	            label,
79	            SEQ.fetch_add(1, Ordering::Relaxed)
80	        ));
81	        fs::create_dir_all(&path).unwrap();
82	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
83	        Tmp { path }
84	    }
85	
86	    fn child(&self, name: impl AsRef<Path>) -> PathBuf {
87	        self.path.join(name)
88	    }
89	}
90	
91	impl Drop for Tmp {
92	    fn drop(&mut self) {
93	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
94	        let _ = fs::remove_dir_all(&self.path);
95	    }
96	}
97	
98	// ---------------------------------------------------------------------------
99	// running the binary
100	// ---------------------------------------------------------------------------
101	
102	struct Run {
103	    rc: i32,
104	    out: Vec<u8>,
105	    err: Vec<u8>,
106	}
107	
108	/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
109	/// wrapper, with the permfail shim preloaded and a trace file configured.
110	fn run_keygen(key: &Path, umask: u32, so: &Path, extra_env: &[(&str, &str)], trace: &Path) -> Run {
111	    let mut cmd = Command::new("/bin/sh");
112	    cmd.arg("-c")
113	        .arg(format!("umask {umask:04o}; exec \"$@\""))
114	        .arg("sh")
115	        .arg(bin())
116	        .arg("keygen")
117	        .arg(key)
118	        .env("LD_PRELOAD", so)
119	        .env("WRAPFILE_TEST_TRACE_FILE", trace);
120	    for (k, v) in extra_env {
121	        cmd.env(k, v);
122	    }
123	    let o = cmd.output().unwrap();
124	    Run {
125	        rc: o.status.code().unwrap_or(-1),
126	        out: o.stdout,
127	        err: o.stderr,
128	    }
129	}
130	
131	// ---------------------------------------------------------------------------
132	// shim trace log
133	// ---------------------------------------------------------------------------
134	
135	struct Event {
136	    kind: String,
137	    attrs: HashMap<String, String>,
138	}
139	
140	impl Event {
141	    fn get(&self, key: &str) -> Option<&str> {
142	        self.attrs.get(key).map(String::as_str)
143	    }
144	
145	    fn ret(&self) -> Option<i64> {
146	        self.get("ret").and_then(|v| v.parse().ok())
147	    }
148	
149	    fn off(&self) -> Option<u64> {
150	        self.get("off").and_then(|v| v.parse().ok())
151	    }
152	
153	    fn hex_bytes(&self) -> Option<Vec<u8>> {
154	        let hex = self.get("hex")?;
155	        assert_eq!(hex.len() % 2, 0, "odd hex in trace line");
156	        Some(
157	            (0..hex.len() / 2)
158	                .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
159	                .collect(),
160	        )
161	    }
162	}
163	
164	fn parse_trace(path: &Path) -> Vec<Event> {
165	    let text = fs::read_to_string(path).unwrap();
166	    text.lines()
167	        .map(|line| {
168	            let mut it = line.split_whitespace();
169	            let kind = it.next().unwrap_or("").to_string();
170	            let attrs = it
171	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
172	                .collect();
173	            Event { kind, attrs }
174	        })
175	        .collect()
176	}
177	
178	/// Create the trace file up front (mode 0644) so that it stays readable even
179	/// when the child runs under umask 0777 -- the shim opens it O_APPEND.
180	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
181	    let p = dir.join(name);
182	    fs::File::create(&p).unwrap();
183	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
184	    p
185	}
186	
187	/// The successful write() calls, in call order: (offset, bytes landed, bytes).
188	fn successful_writes(events: &[Event]) -> Vec<(u64, u64, Option<Vec<u8>>)> {
189	    events
190	        .iter()
191	        .filter(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
192	        .map(|e| {
193	            (
194	                e.off().expect("WRITE event needs off="),
195	                e.ret().unwrap() as u64,
196	                e.hex_bytes(),
197	            )
198	        })
199	        .collect()
200	}
201	
202	/// The landed writes must tile [0, total) exactly: the first starts at 0,
203	/// each continues where the previous ended -- no byte written twice, none
204	/// skipped.
205	fn assert_writes_tile(writes: &[(u64, u64, Option<Vec<u8>>)], total: usize, context: &str) {
206	    assert!(!writes.is_empty(), "{context}: no bytes were ever written");
207	    let mut expect = 0u64;
208	    for (off, n, _) in writes {
209	        assert_eq!(
210	            *off, expect,
211	            "{context}: write at offset {off} overlaps or leaves a gap (expected {expect})"
212	        );
213	        expect += n;
214	    }
215	    assert_eq!(
216	        expect as usize, total,
217	        "{context}: writes must add up to exactly {total} bytes, got {expect}"
218	    );
219	}
220	
221	fn reconstruct(writes: &[(u64, u64, Option<Vec<u8>>)]) -> Vec<u8> {
222	    writes
223	        .iter()
224	        .flat_map(|(_, _, hex)| hex.clone().expect("TRACE_BYTES must be on"))
225	        .collect()
226	}
227	
228	/// The write() calls that accepted 0 bytes while reporting no error.
229	fn zero_writes<'a>(events: &'a [Event]) -> Vec<&'a Event> {
230	    events
231	        .iter()
232	        .filter(|e| e.kind == "WRITE" && e.ret() == Some(0))
233	        .collect()
234	}
235	
236	/// Bytes the program handed to write() calls that accepted none of them.
237	fn rejected_offerings(events: &[Event]) -> Vec<u8> {
238	    zero_writes(events)
239	        .iter()
240	        .flat_map(|e| e.hex_bytes().expect("TRACE_BYTES must be on"))
241	        .collect()
242	}
243	
244	// ---------------------------------------------------------------------------
245	// filesystem assertions
246	// ---------------------------------------------------------------------------
247	
248	fn mode_of(path: &Path) -> u32 {
249	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
250	}
251	
252	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
253	    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
254	}
255	
256	/// The full success contract: exit 0, empty stderr, only the save-location
257	/// line on stdout, and exactly 32 raw key bytes in a 0600 file that leaks
258	/// nowhere.
259	fn assert_success(key: &Path, run: &Run) -> Vec<u8> {
260	    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
261	    assert!(
262	        run.err.is_empty(),
263	        "stderr must be empty on success, got {}",
264	        String::from_utf8_lossy(&run.err)
265	    );
266	    assert_eq!(
267	        run.out,
268	        format!("Key saved to {}\n", key.display()).into_bytes(),
269	        "stdout must be exactly the save-location message"
270	    );
271	
272	    let meta = fs::metadata(key).expect("key file must exist on success");
273	    assert_eq!(meta.len() as usize, KEY_LEN, "key must be exactly 32 bytes");
274	    assert_eq!(
275	        meta.mode() & 0o7777,
276	        MODE_0600,
277	        "key file mode must be exactly 0600"
278	    );
279	
280	    let bytes = fs::read(key).unwrap();
281	    assert_eq!(bytes.len(), KEY_LEN);
282	    assert!(bytes.iter().any(|&b| b != 0), "key must not be all zeroes");
283	    assert!(
284	        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
285	        "key bytes must never appear on stdout/stderr"
286	    );
287	    bytes
288	}
289	
290	/// The failure contract shared by the write-error and fsync-error tests:
291	/// exit 1, an explanation on stderr, no success output, no leaked key
292	/// material, and no trace of this invocation left in the parent directory.
293	fn assert_failed_cleanly(
294	    key: &Path,
295	    run: &Run,
296	    dir: &Path,
297	    allowed_entries: &[&str],
298	    leaked_candidate: &[u8],
299	) {
300	    assert_eq!(run.rc, 1, "an unfinishable save must exit 1");
301	    assert!(
302	        run.out.is_empty(),
303	        "no success message may be printed on failure, got {}",
304	        String::from_utf8_lossy(&run.out)
305	    );
306	    assert!(!run.err.is_empty(), "stderr must explain the failure");
307	    let stderr = String::from_utf8_lossy(&run.err);
308	    assert!(
309	        stderr.contains(&key.display().to_string()),
310	        "stderr should name the target path, got: {stderr}"
311	    );
312	    assert!(
313	        !contains_slice(&run.out, leaked_candidate)
314	            && !contains_slice(&run.err, leaked_candidate),
315	        "key material must never leak to stdout/stderr, even on failure"
316	    );
317	
318	    assert!(
319	        !key.exists(),
320	        "the file this invocation created must be removed after the failure"
321	    );
322	    let mut leftovers: Vec<String> = fs::read_dir(dir)
323	        .unwrap()
324	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
325	        .filter(|n| !allowed_entries.contains(&n.as_str()))
326	        .collect();
327	    leftovers.sort();
328	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
329	}
330	
331	/// Key material must not surface on stdout/stderr in any encoding: not as
332	/// raw bytes, and not as a hex (or other text) rendering.
333	fn assert_key_material_not_leaked(run: &Run, material: &[u8], what: &str) {
334	    assert!(
335	        !contains_slice(&run.out, material) && !contains_slice(&run.err, material),
336	        "{what} must never appear on stdout/stderr as raw bytes"
337	    );
338	    let hex: String = material.iter().map(|b| format!("{b:02x}")).collect();
339	    let out = String::from_utf8_lossy(&run.out);
340	    let err = String::from_utf8_lossy(&run.err);
341	    assert!(
342	        !out.contains(&hex) && !err.contains(&hex),
343	        "{what} must never appear on stdout/stderr in hex form"
344	    );
345	}
346	
347	// A pre-existing object that must survive a failed keygen byte-for-byte.
348	struct Sentinel {
349	    path: PathBuf,
350	    bytes: Vec<u8>,
351	    mode: u32,
352	    inode: u64,
353	}
354	
355	impl Sentinel {
356	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
357	        let path = dir.join(name);
358	        fs::write(&path, bytes).unwrap();
359	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
360	        let meta = fs::metadata(&path).unwrap();
361	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
362	    }
363	
364	    fn assert_untouched(&self) {
365	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
366	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
367	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
368	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
369	    }
370	}
371	
372	// ---------------------------------------------------------------------------
373	// tests
374	// ---------------------------------------------------------------------------
375	
376	#[test]
377	fn partial_writes_save_the_full_key_exactly_once() {
378	    let Some(so) = permfail_so() else {
379	        eprintln!("skipping: permfail shim not available on this target");
380	        return;
381	    };
382	
383	    for umask in UMASKS {
384	        let tmp = Tmp::new("partial");
385	        let key = tmp.child("key");
386	        let trace = prepare_trace(&tmp.path, "trace.log");
387	
388	        // The kernel accepts only one byte per write() call.
389	        let run = run_keygen(
390	            &key,
391	            umask,
392	            &so,
393	            &[
394	                ("WRAPFILE_TEST_PARTIAL_WRITE", "1"),
395	                ("WRAPFILE_TEST_TRACE_BYTES", "1"),
396	            ],
397	            &trace,
398	        );
399	
400	        let on_disk = assert_success(&key, &run);
401	
402	        let events = parse_trace(&trace);
403	        let writes = successful_writes(&events);
404	        assert!(
405	            writes.len() >= KEY_LEN,
406	            "one-byte writes should mean at least 32 write() calls, got {}",
407	            writes.len()
408	        );
409	        // No written byte repeated, no later byte dropped...
410	        assert_writes_tile(&writes, KEY_LEN, "partial writes");
411	        // ...and the bytes the program handed to the kernel are exactly the
412	        // bytes that ended up in the file -- nothing reordered or invented.
413	        assert_eq!(
414	            reconstruct(&writes),
415	            on_disk,
416	            "file content must equal the concatenation of the write() calls"
417	        );
418	
419	        // Success was reported only after the data was synced to disk.
420	        let last_write = events
421	            .iter()
422	            .rposition(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
423	            .unwrap();
424	        let fsynced = events
425	            .iter()
426	            .position(|e| e.kind == "FSYNC" && e.ret() == Some(0))
427	            .expect("the key must be fsynced before success is reported");
428	        assert!(fsynced > last_write, "fsync must follow the last write");
429	    }
430	}
