432	#[test]
433	fn interrupted_writes_are_retried_until_the_key_is_saved() {
434	    let Some(so) = permfail_so() else {
435	        eprintln!("skipping: permfail shim not available on this target");
436	        return;
437	    };
438	
439	    let tmp = Tmp::new("eintr");
440	    let key = tmp.child("key");
441	    let trace = prepare_trace(&tmp.path, "trace.log");
442	
443	    // The first five write() calls are interrupted before any byte is
444	    // consumed; afterwards the system recovers (and still only takes three
445	    // bytes at a time). The same generation must complete, not fail.
446	    let run = run_keygen(
447	        &key,
448	        0o022,
449	        &so,
450	        &[
451	            ("WRAPFILE_TEST_WRITE_EINTR", "5"),
452	            ("WRAPFILE_TEST_PARTIAL_WRITE", "3"),
453	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
454	        ],
455	        &trace,
456	    );
457	
458	    let on_disk = assert_success(&key, &run);
459	
460	    let events = parse_trace(&trace);
461	    let eintrs = events
462	        .iter()
463	        .filter(|e| e.kind == "WRITE" && e.get("errno") == Some("EINTR"))
464	        .count();
465	    assert_eq!(eintrs, 5, "all injected EINTRs must have been observed");
466	
467	    // The interruption consumed nothing: the bytes that eventually landed
468	    // still tile [0, 32) exactly once and match the file.
469	    let writes = successful_writes(&events);
470	    assert_writes_tile(&writes, KEY_LEN, "writes after EINTR");
471	    assert_eq!(reconstruct(&writes), on_disk);
472	}
