474	#[test]
475	fn unrecoverable_write_error_fails_and_removes_the_partial_file() {
476	    let Some(so) = permfail_so() else {
477	        eprintln!("skipping: permfail shim not available on this target");
478	        return;
479	    };
480	
481	    let tmp = Tmp::new("write-error");
482	    let key = tmp.child("key");
483	    let sibling = Sentinel::file(&tmp.path, "sibling", b"do-not-touch", 0o644);
484	    let parent_mode_before = mode_of(&tmp.path);
485	    let trace = prepare_trace(&tmp.path, "trace.log");
486	
487	    // Ten bytes land (4 + 4 + 2), then every further write fails with EIO.
488	    let run = run_keygen(
489	        &key,
490	        0o022,
491	        &so,
492	        &[
493	            ("WRAPFILE_TEST_PARTIAL_WRITE", "4"),
494	            ("WRAPFILE_TEST_FAIL_WRITE_AFTER", "10"),
495	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
496	        ],
497	        &trace,
498	    );
499	
500	    let events = parse_trace(&trace);
501	    let writes = successful_writes(&events);
502	    // The failure really happened mid-write: part of the key was on disk.
503	    assert_writes_tile(&writes, 10, "writes before the error");
504	    assert!(
505	        events
506	            .iter()
507	            .any(|e| e.kind == "WRITE" && e.get("errno") == Some("EIO")),
508	        "the unrecoverable write error must have been injected"
509	    );
510	    assert!(
511	        events.iter().all(|e| e.kind != "FSYNC"),
512	        "an incomplete key must never be synced as if complete"
513	    );
514	    let partial_key = reconstruct(&writes);
515	    assert_eq!(partial_key.len(), 10);
516	
517	    assert_failed_cleanly(&key, &run, &tmp.path, &["sibling", "trace.log"], &partial_key);
518	    sibling.assert_untouched();
519	    assert_eq!(
520	        mode_of(&tmp.path),
521	        parent_mode_before,
522	        "parent directory permissions must be untouched"
523	    );
524	
525	    // The failure was transient: a retry without the fault saves a full key.
526	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
527	    let run2 = run_keygen(&key, 0o022, &so, &[], &trace2);
528	    assert_success(&key, &run2);
529	    sibling.assert_untouched();
530	}
